"""Capacity-curve sweep with an online audit of the four structural laws.

Given a nested chain of sub-batteries and a label, the sweep returns, for every k:
the capacity I(k) = I(joint reading of the first k dials ; label), the additive
bookkeeping sum of single-dial informations, the deficit between them, the ceiling H(L),
and the residual gap.  While sweeping it checks monotonicity of the curve, the ceiling
bound, the sign of the deficit, and the independence hypothesis that makes the deficit
provably non-decreasing.
"""

from __future__ import annotations

import math
from collections import Counter
from typing import Dict, Hashable, List, Sequence, Tuple

Reading = Hashable


def entropy_bits(values: Sequence[Reading]) -> float:
    total = len(values)
    if total == 0:
        return 0.0
    counts = Counter(values)
    return -sum((c / total) * math.log2(c / total) for c in counts.values())


def pair(f: Sequence[Reading], g: Sequence[Reading]) -> List[Tuple[Reading, Reading]]:
    return list(zip(f, g))


def mutual_information_bits(f: Sequence[Reading], g: Sequence[Reading]) -> float:
    return entropy_bits(f) + entropy_bits(g) - entropy_bits(pair(f, g))


def capacity_sweep(
    dials: Sequence[Sequence[Reading]], labels: Sequence[Reading], tolerance: float = 1e-9
) -> Tuple[List[Dict[str, float]], Dict[str, bool]]:
    """Sweep the nested chain and audit the laws.

    Complexity: O(nN log N) for n dials and a population of size N (sorting/hashing the
    joint keys once per prefix), with O(N) working memory.
    """
    ceiling = entropy_bits(labels)
    marginals = [mutual_information_bits(d, labels) for d in dials]
    rows: List[Dict[str, float]] = []
    reading: List[Tuple[Reading, ...]] = [() for _ in labels]
    independence_ok = True
    for k, dial in enumerate(dials, start=1):
        if k > 1:
            overlap = mutual_information_bits(reading, dial)
            independence_ok = independence_ok and overlap <= tolerance
        reading = [cell + (value,) for cell, value in zip(reading, dial)]
        info = mutual_information_bits(reading, labels)
        additive = sum(marginals[:k])
        rows.append(
            {
                "k": float(k),
                "capacity": info,
                "additive": additive,
                "deficit": info - additive,
                "ceiling": ceiling,
                "gap": ceiling - info,
                "pct_of_ceiling": 100.0 * info / ceiling if ceiling > 0 else float("nan"),
            }
        )
    audit = {
        "curve_non_decreasing": all(
            rows[i]["capacity"] <= rows[i + 1]["capacity"] + tolerance
            for i in range(len(rows) - 1)
        ),
        "below_ceiling": all(row["capacity"] <= row["ceiling"] + tolerance for row in rows),
        "deficit_non_decreasing": all(
            rows[i]["deficit"] <= rows[i + 1]["deficit"] + tolerance
            for i in range(len(rows) - 1)
        ),
        "dials_independent": independence_ok,
        "saturated": bool(rows) and abs(rows[-1]["gap"]) <= tolerance,
    }
    return rows, audit


if __name__ == "__main__":
    moduli = (2, 3, 5, 7, 11, 13)
    blocks = (3, 5, 7, 11, 13)
    modulus = math.prod(moduli)
    dials = [[x % m for x in range(modulus)] for m in moduli]
    labels = [
        tuple((x % moduli[i] + x % moduli[i + 1]) % blocks[i] for i in range(len(blocks)))
        for x in range(modulus)
    ]
    rows, audit = capacity_sweep(dials, labels)
    for row in rows:
        print(
            f"k={int(row['k'])}  I={row['capacity']:7.4f}  additive={row['additive']:7.4f}  "
            f"deficit={row['deficit']:+7.4f}  {row['pct_of_ceiling']:6.2f}% of ceiling"
        )
    print(audit)
